  ('Shoshone-Bannock Tribal Museum', 'shoshone-bannock-tribal-museum', 'museums', 43.02179, -112.41134, 'Fort Hall', 'ID', 'Museum on the Fort Hall Reservation presenting Shoshone-Bannock culture, history and art from a tribal perspective. Visit only during public hours and follow all reservation/site rules.', 'limited', 'https://idahohighcountry.org/item/shoshone-bannock-tribal-museum/', null, 'America/Denver', now()),
